import { z } from "zod";
import { createDocument } from "zod-openapi";
import { ApiErrorResponseSchema } from "../../../types/api-response"; // Import for error responses
import {
  SendSmsRequestSchema,
  SendSmsResponseSchema,
} from "./schemas/twilioSchemas";

export const createOpenApiDocument = () => {
  const document = createDocument({
    openapi: "3.1.0",
    info: {
      title: "Twilio SMS Integration",
      version: "1.0.0",
      description: "Send SMS messages using Twilio's messaging service.",
    },
    externalDocs: {
      description: "Twilio SMS Documentation",
      url: "https://www.twilio.com/docs/messaging",
    },
    paths: {
      // IMPORTANT: Path keys MUST include the service name prefix
      "/twilio/sms/send": {
        post: {
          summary: "Send an SMS message via Twilio",
          description: `Send an SMS message to a specified phone number using Twilio's messaging service.

**NOTE:** All endpoints are automatically prefixed with /nodes in our system.
The full path for this endpoint is **/nodes/twilio/sms/send**

**AUTHENTICATION:**
1. You'll need your Twilio Account SID and Auth Token from the Twilio Console.
2. Your Twilio phone number must be SMS-enabled.
3. If using a Trial account, recipient numbers must be verified in the Twilio Console.

**WORKFLOW:**
1. Call this endpoint with your message details and authentication.
2. The message will be queued for sending.
3. Response includes message SID and initial status.
4. Status progression: queued -> sending -> sent -> delivered/undelivered.

**ERROR HANDLING:**
- Returns 500 on internal server errors, authentication failures, or invalid phone numbers.
- Check the \`message\` and \`error.details\` fields in the response for specific information.
- Input validation errors (400) are handled by middleware before this endpoint is reached.

**BEST PRACTICES:**
- Always use E.164 format for phone numbers: +[country code][number].
- US/Canada numbers example: +12125551234.
- Keep messages under 1600 characters to avoid segmentation.
- For high volume, consider using messaging services instead.`, // Kept original description
          tags: ["Twilio"],
          requestBody: {
            required: true,
            description:
              "SMS message parameters including authentication and message content",
            content: {
              "application/json": {
                schema: SendSmsRequestSchema, // Reference the imported Zod schema
              },
            },
          },
          responses: {
            "200": {
              description: "SMS message sent successfully.",
              content: {
                "application/json": {
                  schema: SendSmsResponseSchema, // Reference the imported Zod schema
                },
              },
            },
            "500": {
              description: "Internal Server Error or Service Error",
              content: {
                "application/json": {
                  schema: ApiErrorResponseSchema, // Use the common error schema
                },
              },
            },
          },
        },
      },
      // Path for the OpenAPI spec itself (local to the node)
      "/twilio/openapi.json": {
        post: {
          summary: "Get OpenAPI Documentation for Twilio Node",
          description: `Retrieve the OpenAPI specification specifically for this Twilio node.

**Full Path:** **/nodes/twilio/openapi.json**

**RESPONSE:**
- Returns the complete OpenAPI specification document for the Twilio node.
- Useful for understanding the specific capabilities and schemas of this node.`, // Updated description for clarity
          tags: ["Twilio"],
          // No request body needed for this endpoint
          responses: {
            "200": {
              description: "OpenAPI specification retrieved successfully.",
              content: {
                "application/json": {
                  // Define a schema for the response (the OpenAPI doc itself)
                  // Using a generic object passthrough as the exact structure can be large/complex
                  schema: z.object({}).passthrough().openapi({
                    description:
                      "The OpenAPI specification document for the Twilio node.",
                  }),
                  // Note: Returning the *entire* doc means this isn't wrapped by SuccessResponseSchema
                },
              },
            },
            "500": {
              description: "Failed to generate OpenAPI documentation.",
              content: {
                "application/json": {
                  schema: ApiErrorResponseSchema,
                },
              },
            },
          },
        },
      },
    },
    // Components section will be auto-generated by zod-openapi based on referenced schemas
    components: {
      // schemas: { ... } // Auto-populated
    },
  });

  // Add custom metadata as per ROUTE_STANDARDS.md
  return {
    ...document,
    meta: {
      tags: ["SMS", "Messaging", "Communication"], // Refined tags
      provider: "Twilio",
      category: "Communication", // Changed category
      imageUrl:
        "data:image/png;base64,",
      sourceUrl: "https://www.twilio.com/docs/messaging",
      async: false, // This operation is synchronous (request/response)
      complexity: "low",
    },
  };
};
